package main

import (
	"errors"
	"math"
	"sort"
)

// Basic Arithmetic
func Add(a, b int) int { return a + b }
func Subtract(a, b int) int { return a - b }
func Multiply(a, b int) int { return a * b }
func Divide(a, b int) (int, error) {
	if b == 0 {
		return 0, errors.New("cannot divide by zero")
	}
	return a / b, nil
}

// Float operations
func FloatAdd(a, b float64) float64 { return a + b }
func FloatDivide(a, b float64) (float64, error) {
	if b == 0 {
		return 0, errors.New("cannot divide by zero")
	}
	return a / b, nil
}

// Scientific
func Power(a, b float64) float64 { return math.Pow(a, b) }
func Sqrt(a float64) (float64, error) {
	if a < 0 {
		return 0, errors.New("negative square root")
	}
	return math.Sqrt(a), nil
}

// Trig
func Sin(a float64) float64 { return math.Sin(a) }
func Cos(a float64) float64 { return math.Cos(a) }
func Tan(a float64) float64 { return math.Tan(a) }

// Stats
func Mean(data []float64) float64 {
	if len(data) == 0 { return 0 }
	sum := 0.0
	for _, v := range data {
		sum += v
	}
	return sum / float64(len(data))
}

func Median(data []float64) float64 {
	if len(data) == 0 { return 0 }
	temp := make([]float64, len(data))
	copy(temp, data)
	sort.Float64s(temp)
	mid := len(temp) / 2
	if len(temp) % 2 == 0 {
		return (temp[mid-1] + temp[mid]) / 2
	}
	return temp[mid]
}

func GCD(a, b int) int {
	for b != 0 {
		a, b = b, a % b
	}
	return a
}

func IsPrime(n int) bool {
	if n <= 1 { return false }
	for i := 2; i <= int(math.Sqrt(float64(n))); i++ {
		if n % i == 0 { return false }
	}
	return true
}

func Fibonacci(n int) int {
	if n <= 1 { return n }
	a, b := 0, 1
	for i := 2; i <= n; i++ {
		a, b = b, a+b
	}
	return b
}

// Factorial
func Factorial(n int) (int, error) {
	if n < 0 { return 0, errors.New("negative factorial") }
	if n == 0 { return 1, nil }
	res := 1
	for i := 1; i <= n; i++ {
		res *= i
	}
	return res, nil
}

func Max(a, b int) int {
	if a > b { return a } 
	return b
}

func Min(a, b int) int {
	if a < b { return a }
	return b
}

func Abs(a int) int {
	if a < 0 { return -a }
	return a
}

// Geometry
func CircleArea(radius float64) float64 {
	return math.Pi * radius * radius
}

func RectangleArea(l, w float64) float64 {
	return l * w
}

// Matrix (Simple)
func MatrixAdd(m1, m2 [][]int) ([][]int, error) {
	if len(m1) != len(m2) || len(m1[0]) != len(m2[0]) {
		return nil, errors.New("dim mismatch")
	}
	res := make([][]int, len(m1))
	for i := range m1 {
		res[i] = make([]int, len(m1[0]))
		for j := range m1[0] {
			res[i][j] = m1[i][j] + m2[i][j]
		}
	}
	return res, nil
}

// Logic
func And(a, b bool) bool { return a && b }
func Or(a, b bool) bool { return a || b }
func Xor(a, b bool) bool { return a != b }
func Not(a bool) bool { return !a }

